    if(id==='parchi')return ['parchi','ristoro'].includes(r.mode);
    if(id==='ballo')return r.mode==='ballo';
    if(id==='cultura')return mode?culture&&(mode==='altre'?!['ballo','palestre','musei','parchi','ristoro'].includes(r.mode):r.mode===mode):r.mode==='musei'||(!['ballo','palestre','parchi','ristoro'].includes(r.mode)&&fields.includes('Attività culturali e artistiche'));
    if(id==='giochi')return r.journey==='giochi'&&(!mode||r.mode===mode);
